@@ -54,4 +55,27 @@ int max_3(int a, int b, int c)
         return b;
     else
         return c;
+}
+
+int memcpy_custom(char** dst, char* src, unsigned long long len)
+{
+    char* dst_local = (char*)calloc(len, sizeof(char));
+    char* src_local = src;
+    int k;
+
+    if (dst_local)
+    {
+        *dst = dst_local;
+        for (k = 0; k < len; k++)
+        {
+            dst_local[k] = src_local[k];
+        }
+    }
+    else
+    {
+        free(dst_local);
+        free(src_local);
+        return RI_ERR_ALLOC;
+    }
+    return 0;
 }
